INSERT INTO `fabrication_orders` (`id`, `user_id`, `account_id`, `assigned_employee_id`, `customer_name`, `phone`, `address`, `sales_rep`, `sales_rep_phone`, `city`, `zip_code`, `po_number`, `notes`, `image`, `created_at`, `updated_at`, `admin_status`) VALUES
(1, NULL, 5, NULL, 'Lettie Haynes', '(817)995-2002', '202 Durango', 'James Stopar', '509-999-2939', 'Trophy Club', '76262', '', 'vanity sink in secondary bath- need 2\' x 2\' for shower bench, 6\" x 5\' for shower curb, and 2\' x 3\' for vanity counter. looking for remnants. Contact James to schedule template appointment. Customer has sink and faucet.', '', '2026-04-29 15:30:31', '2026-04-29 15:30:31', 'new'),
(2, NULL, 5, NULL, 'Marc & Lori Springer', '2146841303', '1305 Glouchester Dr.', 'Brian Johnson', '6306594195', 'Garland', '75040', '', 'Need A quote for Prima BQ8616 Polished & Misterio Gold BQ8820\r\nPlease note window ledge to be same material as countertops.', '1778105974_SPRINGER, MARC COUNTERTOP BLUEPRINT.pdf', '2026-05-06 22:19:34', '2026-05-06 22:19:34', 'new'),
(3, NULL, 5, NULL, 'Davis, Genevieve', '973-943-2303', '3600 Chateaux Ln', 'Michele Cochran', '817-994-3687', 'Hurst', '76053', 'Counter top', 'Please measure for Template on Tuesday May 19th 10:00 am', '', '2026-05-15 19:03:11', '2026-05-15 19:03:11', 'new'),
(4, NULL, 2, NULL, 'Vince and Vicki Adame', '325-212-4972', '3530 Whitley Rd', 'Wendy Prock', '972-978-1887', 'Wylie', '75098', '3460', 'The customer did not pick out a standard edge with us.  Can you have them select edge at time of template?  Also,  they want quartz  included on the backsplash on the sink side ONLY.  The phone number provided is Vicki\'s but here is an alternate husbands phone number: 910-915-5420,  it is around 80 sf...   We are also doing plumbing so keep me informed before scheduling.  We don\'t want to leave them with no sink hook up over a weekend so prefer no Friday install unless the customer requests.', '1779213322_Wylie Carpet.jpg', '2026-05-19 17:33:54', '2026-05-19 17:55:22', 'new'),
(5, NULL, 2, NULL, 'Kay Cato', '972-948-0465', '416 N Winding Oak Dr', 'Wendy', '9729781887', 'Wylie', '75098', '3461', 'I have texted the customer to confirm the edge, and I\'m always confused about the thickness on Vicostone.  I don\'t know if it matters.   We are doing a tub surround in there as well so I\'m trying to coordinate a plumber to install a new tub, valve and reconnect sinks at the same time if possible.  Please advise of template date and once I know when we can start the shower, I will see if we can coordinate dates to work out for plumbing. Actual 27 sf but I think minimum is 30.', '', '2026-05-20 15:15:49', '2026-05-28 16:43:35', 'new'),
(6, NULL, 2, NULL, 'Teri Sundberg', '214-912-2380', '1212 Braddock Way', 'Wendy', '972-442-7319', 'Wylie', '75098', '3466', 'PLEASE NOTE:  We received deposit, but we are waiting on the electrician to disconnect and us to be able to go by and cut down bar before template.  Once we have that date, we will schedule the template.  I just want to make sure the color is in stock with MSI,  the white with black veins.  Also customer requested Anthracite, black composite, sink 60/40 with the low divide.  Can you make sure you can get that as well? Husband, Erik, 972-415-5261 alt number.', '', '2026-05-26 17:04:52', '2026-05-26 17:04:52', 'new'),
(7, NULL, 5, NULL, 'Genevieve Davis', '973-943-2303', '3600 Chateaux Ln', 'Michele Cochran', '817-994-3687', 'Hurst', '76053', 'Davis', 'Please remove existing countertop -- Customer to supply Sink and Faucet', '', '2026-05-27 17:48:10', '2026-05-27 17:48:10', 'new'),
(9, NULL, 18, NULL, 'Carla Haddock', '214-551-9503', '3409 Nations Dr', 'Jeff Cappon', '214-551-9503', 'Frisco', '75034', 'Carla Haddock', 'Send invoices invoices@gcflooringpros.com\r\n2 sinks, floors being installed so waterfall measure needs to account for that. customer doing pop-up, quartz backsplash in kitchen & laundry', '', '2026-06-09 13:31:11', '2026-06-09 13:45:05', 'new'),
(10, NULL, 25, NULL, 'Mike Freeman', '(214) 578-8556', '560 E. New Hope Rd.', 'Kennedy Peralta', '214-643-5605', 'McKinney', '75071', 'EP-47147', 'Discuss the edge and the sink style choices with the customer. Please only discuss standard options with the customer. Nothing with an extra cost attached. Approximately 60 sf', '', '2026-06-11 19:05:45', '2026-06-17 14:56:30', 'new'),
(11, NULL, 18, NULL, 'GC - Jeff', '2145519503', '4319 Liam Drive', 'Jeff and Ivan', '2145519503', 'Frisco', '75034', '', 'We can ship the slab(s) to you unless you can do a per foot that will be less $', '', '2026-06-22 14:46:48', '2026-06-22 14:53:40', 'new'),
(12, NULL, 2, NULL, 'Patrick and Anne Neshyba', '512-350-4594', '2414 Maple Ridge Dr', 'Chris', '2143166309', 'Garland', '75044', '3504', 'Chris said template Thursday between 12:30 and 2:00 to meet Patrick, 512-350-4594.  It does not look like they picked an edge, can you confirm at time of template.  They are providing their own plumbing so make arrangements with them for installation.  I believe they have other tradesmen working in the house.', '', '2026-06-23 16:44:37', '2026-06-23 16:44:37', 'new'),
(13, NULL, 25, NULL, 'RAMESH & HEMA CHINNASAMY', '732-881-2018', '506 COTTON GIN TRAIL', 'QUSAI', '469-247-4684', 'ALLEN', '75013', 'WP-47263', 'KITCHEN ISLAND SIZE 101\"X52\", NEED EXTRA FOR OVERHANG', '', '2026-07-13 19:28:44', '2026-07-13 19:28:44', 'new'),
(14, 2, NULL, NULL, 'Joe Jackson', '972-834-5407', '800 West Shore Dr', 'Jay Moody', '9728969355', 'Richardson', '75080', '', 'Customer\'s wife still needs to confirm quartz selection, but they want to move forward with the template and try to get installed asap. It\'s the master vanity w 2 sinks, including 8\" backsplash on the lower vanity section and 4\" on the higher vanity section.', '1784903883_Vanity Measure Jackson.png', '2026-07-24 14:38:03', '2026-07-24 14:38:03', 'new'),
(15, NULL, 27, NULL, 'Rick Uvence', '469-500-8727', '927 Pelican Dr', 'Rick Uvence', '469-500-8727', 'Allen', '75013', '', 'This is roughly 18sf with 4\" backsplash at the ends. Cut out for drop in sink. Customer is: Aaron Wynn', '', '2026-08-06 00:27:51', '2026-08-06 00:27:51', 'new'),
(16, NULL, 5, NULL, 'Victoria Marshall', '972-824-7567', '2102 Terry Ave', 'Michele Cochran', '817-994-3687', 'Melissa', '75454', 'Marshall', 'Please advise when you can measure, we are moving extremely fast on this project. Thank you', '', '2026-08-12 20:01:17', '2026-08-12 20:01:17', 'new'),
(17, NULL, 25, NULL, 'Rachel Farber', '9727436012', '4541 Lone Tree Dr', 'Rania Okasheh', '616-485-9145', 'Plano', '75093', 'WP-47389', 'J& J vanities 2 one tear out cultured marble the other one is Newley built with backsplash \r\nPlease confirm the edge with client as well as the rectangular sinks.\r\nCustomer came down and chose the materials', '', '2026-08-18 17:39:43', '2026-08-18 17:39:43', 'new'),
(18, NULL, 30, NULL, 'Customer Name', '143-457-1245', '123 Street ST', 'Scott Adams', '4693963105', 'Dallas', '75201', '', '', '', '2026-08-20 17:28:50', '2026-08-20 17:54:59', 'new'),
(21, 2, NULL, 6, 'David and Laura Hirsch', '817-797-9348', '793 Maplewood', 'Scott Gaulden', '940-566-6169', 'Keller', '76248', '', 'Add Threshold 64x7', '', '2026-09-09 14:35:49', '2026-09-09 14:36:48', 'new'),
(22, NULL, 25, 5, 'Edward Clark and Barbara Richerts', '214-797-4059 Barbara', '4313 Southgate dr', 'Curtis Ohme', '214-548-0168 cell or', 'Plano', '75024', 'WP-47368', 'Install quartz in kitchen countertops and backsplash. Install just countertop on cabinet in breakfast nook area with no backsplash. Will be ready for measurement the week of 9/14. The painter will be done 9/16.', '', '2026-09-10 14:38:49', '2026-09-10 19:23:09', 'new'),
(23, NULL, 25, NULL, 'Kathy Peterson', '469-222-6538', '18412 Featherwood DR', 'Rania', '616-485-9145', 'Dallas', '75252', 'WP-47519', 'Rocky Quarts from Texas Specialized Quartz & Granite for 3 vanities and a bar area, sinks are included 3 undermount from Ts client will chose on Wednesday to choose color and confirm edging sinks and one vessel sink in powder room client will provide, if she chose not to do vessel sink and undermount please call Rania', '', '2026-09-14 20:44:09', '2026-09-14 20:44:09', 'new'),
(24, NULL, 27, NULL, 'Laura Borden', '(214) 477-5621', '2701 Nova Dr', 'Rick Uvence - ALLEN FLOORS', '(469) 500-8727', 'Garland', '75044', 'PO# Borden', '50/50 UNDERMOUNT SINK PROVIDED BY TEXAS SPECIALIZED', '', '2026-09-15 16:00:35', '2026-09-15 16:00:35', 'new'),
