CREATE TABLE `faq_items` (
  `id` int(11) NOT NULL,
  `question` varchar(500) NOT NULL,
  `answer` text NOT NULL,
  `category` varchar(100) DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `status` enum('published','draft') NOT NULL DEFAULT 'published',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `faq_items`
--

INSERT INTO `faq_items` (`id`, `question`, `answer`, `category`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(14, 'What services do you offer at Texas Specialized Quartz & Granite?', '<p>We specialize in custom fabrication and installation of premium countertops including:</p><ul><li><strong>Granite countertops</strong> for kitchens and bathrooms</li><li><strong>Quartz countertops</strong> for residential and commercial spaces</li><li><strong>Marble countertops</strong> for luxury applications</li><li>Custom countertops for bars, islands, and outdoor kitchens</li><li>Countertop repair and restoration services</li></ul>', NULL, 10, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37'),
(15, 'What is your new address in Carrollton, TX?', '<p>Our new showroom and fabrication facility is located at:</p><address><strong>Texas Specialized Quartz & Granite</strong><br>2943 Ladybird Ln, Dallas, TX 75220, United States<br></address><p>Visit our Carrollton countertop showroom to see our extensive slab selection.</p>', NULL, 20, 'published', '2026-04-24 20:10:37', '2026-08-13 06:44:33'),
(16, 'How do I get a free countertop estimate?', '<p>Getting a free countertop quote is easy:</p><ol><li><strong>Call us</strong> at +1 (469) 814-0555 for a phone consultation</li><li><strong>Visit our showroom</strong> in Carrollton for an in-person estimate</li><li><strong>Use our online form</strong> to request a virtual quote</li><li><strong>Schedule a free home visit</strong> for measurements and material selection</li></ol>', NULL, 30, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37'),
(17, 'Do you offer same-day countertop installation?', '<p>Due to the custom nature of countertop fabrication, we typically schedule installations within <strong>3–7 business days</strong> after final measurements and material selection. This ensures:</p><ul><li>Precise custom fabrication</li><li>Quality control checks</li><li>Proper sealing and finishing</li><li>Professional installation by experienced technicians</li></ul>', NULL, 40, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37'),
(18, 'What\'s the difference between granite, marble, and quartz countertops?', '<div class=\"row\"><div class=\"col-md-4\"><h4>Granite Countertops</h4><ul><li><strong>Natural stone</strong> with unique patterns</li><li>Excellent heat resistance</li><li>Requires annual sealing</li><li>Perfect for busy kitchens</li></ul></div><div class=\"col-md-4\"><h4>Quartz Countertops</h4><ul><li><strong>Engineered stone</strong> with consistent colors</li><li>Non-porous, no sealing required</li><li>Stain and scratch resistant</li><li>Low maintenance option</li></ul></div><div class=\"col-md-4\"><h4>Marble Countertops</h4><ul><li><strong>Luxury natural stone</strong></li><li>Classic veining patterns</li><li>Softer surface, requires care</li><li>Ideal for bathrooms and pastry stations</li></ul></div></div>', NULL, 50, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37'),
(19, 'Can I visit your Dallas countertop showroom?', '<p>Yes! You can visit our Dallas showroom to explore a wide selection of granite, quartz, and marble slabs, compare finishes, and consult with our design experts about your project.</p>\r\n\r\n<p><strong>Showroom Hours:</strong> Monday–Friday 9:00 AM – 5:00 PM, Saturday by appointment.</p>', NULL, 60, 'published', '2026-04-24 20:10:37', '2026-04-27 17:28:49'),
(20, 'Do you offer warranty on countertop installation?', '<p>Yes, we stand behind our work with comprehensive warranties:</p><ul><li><strong>1-Year Workmanship Warranty:</strong> Covers installation quality</li><li><strong>Manufacturer Warranties:</strong> Vary by material (typically 10-25 years for quartz)</li><li><strong>Sealing Warranty:</strong> For natural stone countertops</li></ul><p>All warranty details are provided in writing with your installation contract.</p>', NULL, 70, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37'),
(21, 'Do you remove old countertops during installation?', '<p>Yes, we provide complete countertop removal and disposal services as part of our installation package. This includes:</p><ul><li>Professional removal of existing countertops</li><li>Safe disposal of old materials</li><li>Preparation of the substrate</li><li>Protection of surrounding areas during removal</li></ul><p>There are no hidden fees for removal – it\'s included in your quoted price.</p>', NULL, 80, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37'),
(22, 'How long does countertop installation take?', '<p>Installation time varies by project size:</p><ul><li><strong>Standard Kitchen:</strong> 4-6 hours</li><li><strong>Bathroom Vanity:</strong> 2-3 hours</li><li><strong>Kitchen Island:</strong> 3-4 hours</li><li><strong>Large Commercial Project:</strong> 1-2 days</li></ul><p>We work efficiently to minimize disruption to your home or business.</p>', NULL, 90, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37'),
(23, 'Are countertops sealed before installation?', '<p>Yes, we follow industry-best practices for countertop preparation:</p><ul><li><strong>Granite & Marble:</strong> Professionally sealed before installation</li><li><strong>Quartz:</strong> No sealing required (non-porous material)</li><li><strong>Additional Sealing:</strong> Available for extra protection in high-use areas</li></ul><p>We use premium sealants that provide long-lasting protection against stains and moisture.</p>', NULL, 100, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37'),
(24, 'Do you work on weekends?', '<p>Our schedule is designed to accommodate our customers:</p><ul><li><strong>Showroom:</strong> Open Saturdays by appointment</li><li><strong>Installations:</strong> Primarily Monday-Friday</li><li><strong>Emergency Services:</strong> Available for urgent needs</li><li><strong>Consultations:</strong> Flexible scheduling including evenings</li></ul><p>Contact us to discuss weekend or after-hours options for your project.</p>', NULL, 110, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37'),
(25, 'Do you offer custom edge profiles for countertops?', '<p>Yes! We offer a wide range of custom edge profiles to match your design style:</p><div class=\"row\"><div class=\"col-md-6\"><h5>Popular Edge Profiles:</h5><ul><li>Eased Edge (standard)</li><li>Beveled Edge</li><li>Bullnose Edge</li><li>Ogee Edge</li><li>Dupont Edge</li></ul></div><div class=\"col-md-6\"><h5>Premium Options:</h5><ul><li>Waterfall Edge</li><li>Chiseled Edge</li><li>Mitered Edge</li><li>Custom designs</li></ul></div></div><p>Visit our showroom to see physical samples of each edge profile.</p>', NULL, 120, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37'),
(26, 'What areas in North Texas do you serve?', '<p>We proudly serve the entire North Texas region including:</p><div class=\"row\"><div class=\"col-md-6\"><ul><li>Carrollton</li><li>Plano</li><li>Frisco</li><li>McKinney</li><li>Allen</li></ul></div><div class=\"col-md-6\"><ul><li>Dallas</li><li>Richardson</li><li>Lewisville</li><li>Flower Mound</li><li>The Colony</li></ul></div></div><p>Contact us to confirm service availability in your specific area.</p>', NULL, 130, 'published', '2026-04-24 20:10:37', '2026-04-24 20:10:37');

