(71, 'Jacob Catalano', 'jacob@outsideagent.ai', 'Need help applying AI to your business?', 'Hi there,\r\n\r\nMy name\'s Jacob Catalano. I run a small AI agency based in LA — we design and deploy AI agents for businesses like yours. Some handle customer-facing work like texting and phone calls, and others handle internal processes that aren\'t SMS-based. We\'ve created agents that have handled over 5 million messages and 700,000+ phone calls.\r\n\r\nIf you\'re open to it, I\'d love to hop on a quick call and learn more about how we can support your business.\r\n\r\nBest,\r\nJacob Catalano\r\n+16184254468', '173.198.56.105', 0, '2026-07-20 21:09:56'),
(72, 'Caio Fonseca', 'caio.fonseca@buildsalesbrasil.com.br', 'CAIO FONSECA | GLOBAL TRADE DIVISION | BUILD SALES BRASIL | +55 11 98998-8080', 'Hi,\r\nI’m with Build Sales Brasil, a Brazilian export trading company focused on Brazilian natural stone, processed timber, and selected construction materials.\r\nWe work as a local partner in Brazil, coordinating supplier qualification, market pricing, logistics, export documentation, and shipment follow-up through one point of contact.\r\nOur experience comes from supporting construction and engineering companies across commercial, residential, and corporate projects in Brazil. This has given us practical knowledge of local suppliers, production capabilities, pricing dynamics, quality requirements, and the challenges involved in sourcing reliable materials.\r\nAre you currently requesting quotations for any Brazilian materials? If so, we would be more than happy to schedule an online meeting!\r\nLooking forward to hearing from you.\r\nBest,', '2804:14c:27:80fa:f0ed:712f:4848:337f', 0, '2026-07-21 18:05:04'),
