  `customer_name` varchar(150) NOT NULL,
  `customer_address` varchar(255) NOT NULL,
  `worked_area` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`worked_area`)),
